'use client'

import { cn, useSignal, useSignals } from '@cascivo/core'
import type { CSSProperties, ReactNode, UIEvent } from 'react'
import styles from './virtual-list.module.css'

export interface VirtualListProps<Item> {
  items: Item[]
  /** Fixed row height in px. Rows must all be this tall for positions to be correct. */
  itemHeight: number
  /**
   * Height of the scrolling viewport, in px.
   *
   * Deliberately not a CSS length: the visible row count is computed from this number, and
   * a relative length like `100%` cannot be resolved without measuring. Wrap the list and
   * pass a measured px value if the height has to be fluid.
   */
  height: number
  renderItem: (item: Item, index: number) => ReactNode
  /**
   * Extra rows rendered above and below the visible window, to cover fast scrolling.
   *
   * @defaultValue `3`
   * @see the component manifest
   */
  overscan?: number
  /** Accessible label for the list; defaults to none, so label it when standalone. */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
  className?: string
}

/**
 * Renders only the rows inside the scrolled viewport, so a list of any length costs a
 * constant number of DOM nodes.
 *
 * Row height is fixed: positions are arithmetic rather than measured, which keeps scrolling
 * on the compositor and avoids a layout pass per frame. Each rendered row carries
 * `aria-setsize` and `aria-posinset` for the **full** collection, so assistive technology
 * reports "3 of 10000" rather than the size of the rendered window.
 */
export function VirtualList<Item>({
  items,
  itemHeight,
  height,
  renderItem,
  overscan = 3,
  ariaLabel,
  label,
  className,
}: VirtualListProps<Item>) {
  useSignals()
  const scrollTop = useSignal(0)

  const visibleCount = Math.ceil(height / itemHeight)
  // Anchor the range on the first visible row, not on `first`: deriving `last` from a
  // clamped `first` widens the window by the whole overscan at the top of the list.
  const firstVisible = Math.floor(scrollTop.value / itemHeight)
  const first = Math.max(0, firstVisible - overscan)
  const last = Math.min(items.length, firstVisible + visibleCount + overscan)
  const visible = items.slice(first, last)

  const onScroll = (event: UIEvent<HTMLDivElement>): void => {
    scrollTop.value = event.currentTarget.scrollTop
  }

  const viewportStyle = { blockSize: `${height}px` } as CSSProperties

  return (
    <div
      className={cn(styles['viewport'], className)}
      style={viewportStyle}
      onScroll={onScroll}
      role="list"
      aria-label={ariaLabel ?? label}
      // Rows carry no focusable content of their own, so without this the scroll
      // container is unreachable by keyboard (axe scrollable-region-focusable).
      // Focused, it takes the browser's native arrow/PageUp/PageDown scrolling.
      tabIndex={0}
    >
      {/* Sized to the full collection so the scrollbar reflects real length. */}
      <div className={styles['canvas']} style={{ blockSize: `${items.length * itemHeight}px` }}>
        {visible.map((item, offset) => {
          const index = first + offset
          return (
            <div
              key={index}
              role="listitem"
              aria-setsize={items.length}
              aria-posinset={index + 1}
              className={styles['row']}
              style={{
                blockSize: `${itemHeight}px`,
                transform: `translateY(${index * itemHeight}px)`,
              }}
            >
              {renderItem(item, index)}
            </div>
          )
        })}
      </div>
    </div>
  )
}

@layer cascivo.component {
  .viewport {
    overflow-y: auto;
    overscroll-behavior: contain;
    /* Rows are absolutely placed against this box. */
    position: relative;

    &:focus-visible {
      outline: 2px solid var(--cascivo-color-accent);
      outline-offset: -2px;
    }
  }

  .canvas {
    position: relative;
    inline-size: 100%;
  }

  .row {
    position: absolute;
    inset-inline: 0;
    inset-block-start: 0;
    display: flex;
    align-items: center;
    /* translateY does the placement; the compositor keeps it off the layout path. */
    will-change: transform;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'VirtualList',
  description: 'Renders only the rows inside the viewport, so list length costs no extra DOM',
  category: 'display',
  clientJs: 'required',
  states: ['default'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'items',
      type: 'Item[]',
      required: true,
      description: 'The full collection; only the visible window is rendered',
    },
    {
      name: 'itemHeight',
      type: 'number',
      required: true,
      description: 'Fixed row height in px — every row must be this tall',
    },
    {
      name: 'height',
      type: 'number',
      required: true,
      description:
        'Height of the scrolling viewport, in px — not a CSS length, because the visible row count is computed from it',
    },
    {
      name: 'renderItem',
      type: '(item: Item, index: number) => React.ReactNode',
      required: true,
      description: 'Renders one row',
    },
    {
      name: 'overscan',
      type: 'number',
      required: false,
      default: '3',
      description:
        'Extra rows rendered above and below the visible window, to cover fast scrolling.',
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description: 'Accessible label for the list; label it when the list stands alone',
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: ['--cascivo-color-accent'],
  accessibility: {
    role: 'list',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End'],
  },
  examples: [
    {
      title: 'Basic',
      code: `<VirtualList
  items={Array.from({ length: 10000 }, (_, i) => i)}
  itemHeight={40}
  height={320}
  ariaLabel="Results"
  renderItem={(n) => <span>Row {n + 1}</span>}
/>`,
      description: 'Ten thousand rows cost the same DOM as ten.',
    },
    {
      title: 'Smoother fast scrolling',
      code: `<VirtualList items={rows} itemHeight={40} height={320} overscan={10} renderItem={renderRow} />`,
      description: 'A larger overscan trades DOM nodes for fewer blank frames when flinging.',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['display', 'virtual', 'virtualization', 'list', 'performance', 'scroll'],
  intent: {
    whenToUse: [
      'Lists long enough that rendering every row costs noticeable time or memory (roughly a thousand rows and up)',
      'Log, result and feed views where the collection is already fully in memory',
      'Any list whose length is unbounded and rows are a uniform height',
    ],
    whenNotToUse: [
      'Short lists — the machinery costs more than it saves; use List',
      'Rows of varying height, which this component cannot position without measuring',
      'Content that must be findable with the browser’s in-page search, which cannot see unrendered rows',
    ],
    antiPatterns: [
      {
        bad: 'Passing rows whose real height differs from `itemHeight`',
        good: 'Fix the row height in CSS to match `itemHeight` exactly',
        why: 'Positions are arithmetic, not measured, so a mismatch makes rows overlap or leave gaps that grow with scroll depth',
      },
      {
        bad: 'Reaching for a percentage or `dvh` viewport height',
        good: 'Measure the container and pass a px number',
        why: '`height` drives the visible row count, which cannot be derived from a relative length without measuring',
      },
      {
        bad: 'Fetching the next page inside `renderItem`',
        good: 'Pair with InfiniteScroll, or load before passing `items`',
        why: 'renderItem runs for every row entering the window, including on scroll-back, so a fetch there fires repeatedly',
      },
    ],
    related: [
      {
        name: 'List',
        relationship: 'alternative',
        reason: 'Plain list when the collection is small enough to render whole',
      },
      {
        name: 'InfiniteScroll',
        relationship: 'pairs-with',
        reason: 'Loads further pages into the collection this list renders',
      },
      {
        name: 'DataTable',
        relationship: 'alternative',
        reason: 'Columnar data with sorting and selection rather than a flat row list',
      },
    ],
    a11yRationale:
      'The viewport is a role="list" and each rendered row is a role="listitem" carrying aria-setsize and aria-posinset for the entire collection, so assistive technology announces "row 3 of 10000" rather than the size of the rendered window — the defect that makes naive virtualization unusable with a screen reader. The viewport is also in the tab order, because rows hold plain content rather than focusable controls and a scroll container with nothing focusable inside it is otherwise unreachable without a pointer; once focused it takes the browser’s native arrow, Page and Home/End scrolling. Rows are placed with transform rather than by mutating layout, so scrolling stays on the compositor. Because unrendered rows are absent from the DOM, browser in-page search cannot reach them; provide a real filter or search control alongside any virtualized list, and prefer a non-virtualized list when the collection is small.',
    flexibility: [
      {
        area: 'overscan',
        level: 'flexible',
        note: 'Rows rendered beyond the window (default 3)',
      },
      {
        area: 'itemHeight',
        level: 'strict',
        note: 'Fixed and uniform — variable row heights are not supported',
      },
    ],
  },
}
